{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur l'indemnité journalière et la rente d'invalidité (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle les dispositions et principes applicables à l'allocation des prestations d'assurance en cas d'accident, à la stabilisation de l'état de santé, à l'évaluation de l'invalidité selon la méthode de comparaison des revenus et à l'appréciation des rapports médicaux (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le revenu sans invalidité doit être évalué de la manière la plus concrète possible (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Selon la vraisemblance prépondérante, l'experte psychiatre n'a pas procédé à une nouvelle analyse de la capacité de travail, mais s'est ralliée à l'avis de l'expert neurologue (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "L'experte psychiatre a ainsi estimé que la capacité de travail résiduelle psychiatrique devait être mise en rapport avec les répercussions des affections neurologiques, qui constituaient les diagnostics principaux (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "L'arrêt entrepris retient un revenu sans invalidité de 59'321 fr. 87, ce qui ne prête pas le flanc à la critique (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale confirme le revenu d'invalide de 53'440 fr. 10 fixé par l'intimée, tenant compte d'un abattement de 5 % (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le dernier grief du recourant concernant le revenu d'invalide (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
